def merge(intervals):
    if not intervals:
        return []
    # Sort intervals by start
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [sorted_intervals[0]]
    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or touching, merge them
            merged[-1] = (last[0], max(last[1], current[1]))
        else:
            merged.append(current)
    return merged


def free_gaps(intervals, window):
    ws, we = window
    # Sort intervals by start
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    gaps = []
    current_start = ws
    for interval in sorted_intervals:
        start, end = interval
        # Clip the interval to the window
        start = max(start, ws)
        end = min(end, we)
        if start < end:
            # Add gap before the interval
            if current_start < start:
                gaps.append((current_start, start))
            current_start = end
    # Add the final gap if any
    if current_start < we:
        gaps.append((current_start, we))
    return gaps


def max_overlap(intervals):
    if not intervals:
        return 0
    # Sort intervals by start
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    # Track the end of the current interval and the overlap count
    end = sorted_intervals[0][1]
    overlap = 1
    for interval in sorted_intervals[1:]:
        start, current_end = interval
        if start < end:
            # Overlapping
            overlap += 1
            end = max(end, current_end)
        else:
            # No overlap, reset
            end = current_end
            overlap = 1
    return overlap

import time

class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        self.clock = clock
        self.cache = {}  # key -> (value, timestamp, ttl)
        self.order = []  # list of keys in order of use

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("TTL must be positive")
        # Remove expired entries
        self.evict_expired()
        # Check if the cache is full
        if len(self.cache) >= self.capacity:
            # Evict the least recently used entry
            if self.order:
                lru_key = self.order[0]
                del self.cache[lru_key]
                self.order.pop(0)
        # Add the new entry
        timestamp = self.clock()
        if ttl is None:
            self.cache[key] = (value, timestamp, float('inf'))
        else:
            self.cache[key] = (value, timestamp, timestamp + ttl)
        # Update the order
        if key in self.order:
            self.order.remove(key)
        self.order.append(key)

    def get(self, key, default=None):
        # Remove expired entries
        self.evict_expired()
        if key in self.cache:
            value, timestamp, ttl = self.cache[key]
            # Make the entry the most recently used
            if key in self.order:
                self.order.remove(key)
            self.order.append(key)
            return value
        return default

    def __contains__(self, key):
        # Remove expired entries
        self.evict_expired()
        return key in self.cache

    def __len__(self):
        # Remove expired entries
        self.evict_expired()
        return len(self.cache)

    def keys(self):
        # Remove expired entries
        self.evict_expired()
        return list(self.order)

    def evict_expired(self):
        removed = 0
        # Remove expired entries from the cache
        to_remove = [key for key in self.cache if self.cache[key][2] <= self.clock()]
        for key in to_remove:
            del self.cache[key]
            removed += 1
            if key in self.order:
                self.order.remove(key)
        return removed

